}

results = for contact in contacts {
    # Phone fix
    phone = contact.phone if contact.phone != null else ""
    already_valid = regex.test(phone, "^\\+1\\d{10}$")
    digits = regex.replace(phone, "[^0-9]", "")
    fixed_phone = null
    phone_needs_fix = false
    if not already_valid and phone != "" {
        # US numbers: if 11 digits starting with 1, use +1 + last 10; if 10 digits, +1 + digits
        dlen = text.length(digits)
        new_phone = if dlen == 11 and text.starts_with(digits, "1") {
            return "+" + digits
        } else if dlen == 10 {
            return "+1" + digits
        } else if dlen > 11 and text.starts_with(digits, "1") {
            return "+1" + text.slice(digits, 1, 11)
