            return "+1" + text.slice(digits, dlen - 10, dlen)
        } else {
            return null
        }
        if new_phone != null and new_phone != phone {
            fixed_phone = new_phone
            phone_needs_fix = true
        }
    }

    # Company fill
    company_needs_fix = false
    new_company = null
    company_empty = contact.company == null or contact.company == ""
    if company_empty and contact.email != null and contact.email != "" {
        parts = text.split(contact.email, "@")
        if list.length(parts) >= 2 {
            domain = text.lower(parts[list.length(parts) - 1])
            if domain in domain_map {
                new_company = domain_map[domain]
                company_needs_fix = true
            }
        }
    }

    updated = null
    if phone_needs_fix and company_needs_fix {
        updated = update_contact({ id: contact.id, phone: fixed_phone, company: new_company })
    } else if phone_needs_fix {
        updated = update_contact({ id: contact.id, phone: fixed_phone })
    } else if company_needs_fix {
        updated = update_contact({ id: contact.id, company: new_company })
    }

    return {
        phone_fixed: phone_needs_fix,
        company_filled: company_needs_fix
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
